import React, { useEffect, useRef, useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import * as d3 from 'd3';

const EmbeddingComponent = () => {
	const [embedding, setEmbedding] = useState<number[] | null>(null);
	const svgRef = useRef<SVGSVGElement | null>(null);

	// TanStack Query mutation to POST the text and receive the embedding
	const mutation = useMutation({
		mutationFn: async () => {
			const res = await fetch('http://127.0.0.1:8000/api/embedding/bert', {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify({ text: "This is a sample text for generating word embeddings using BERT." })
			});
			if (!res.ok) throw new Error('Network response was not ok');
			return res.json();
		},
		onSuccess: (data: { embedding: number[] }) => {
			setEmbedding(data.embedding);
		}
	});

	useEffect(() => {
		// Trigger the post request on component mount
		mutation.mutate();
	}, []);

	useEffect(() => {
		if (!embedding || !svgRef.current) return;
		const svg = d3.select(svgRef.current);
		svg.selectAll("*").remove(); // clear previous drawing

		const width = 600, height = 300;
		svg.attr("width", width).attr("height", height);

		// X scale: index of each embedding value
		const xScale = d3.scaleLinear()
			.domain([0, embedding.length - 1])
			.range([40, width - 20]);
		// Y scale: embedding value range
		const yExtent = d3.extent(embedding) as [number, number];
		const yScale = d3.scaleLinear()
			.domain(yExtent)
			.range([height - 30, 20]);

		// Generate line path
		const line = d3.line<number>()
			.x((d, i) => xScale(i))
			.y(d => yScale(d));

		svg.append("path")
			.datum(embedding)
			.attr("fill", "none")
			.attr("stroke", "steelblue")
			.attr("stroke-width", 2)
			.attr("d", line);

		// Add x-axis
		svg.append("g")
			.attr("transform", `translate(0, ${height - 30})`)
			.call(d3.axisBottom(xScale));

		// Add y-axis
		svg.append("g")
			.attr("transform", "translate(40,0)")
			.call(d3.axisLeft(yScale));
	}, [embedding]);

	return (
		<div>
			{mutation.isPending && <p>Loading...</p>}
			{mutation.isError && <p>Error fetching embedding.</p>}
			{embedding && <svg ref={svgRef}></svg>}
		</div>
	);
};

export default EmbeddingComponent;